 "jockeyNotes": [
  {
   "name": "菊沢一樹",
   "k": "新潟|芝1000",
   "text": "千直の成績がずば抜けている。思い切って攻める乗り方が理由と言われる",
   "src": "競馬ラボ 2026・メモ"
  },
  {
   "name": "鮫島克駿",
   "k": "新潟|芝1000",
   "text": "以前は「令和の千直マイスター」と呼ばれた（2020年頃）。ここ5年は新潟にほとんど乗っていない",
   "src": "SPREAD・デイリー 2020"
  },
  {
   "name": "嶋田純次",
   "k": "新潟|芝1000",
   "text": "13番人気を3着に持ってきて、千直の腕が話題になった",
   "src": "スポーツ報知 2026"
  },
  {
   "name": "川田将雅",
   "k": "新潟|芝1000",
   "text": "千直では人気ほど走れないことが多い。枠の影響を受けやすい",
   "src": "SPREAD"
  },
  {
   "name": "丹内祐次",
   "k": "函館",
   "text": "函館出身。2025年の函館でリーディング（初）",
   "src": "北海道新聞 2025"
  },
  {
   "name": "武豊",
   "k": "札幌",
   "text": "2024年夏の札幌で勝ち星を量産し、北海道リーディングを争った",
   "src": "デイリー 2024"
  },
  {
   "name": "横山和生",
   "k": "札幌",
   "text": "2026年の札幌でリーディング",
   "src": "デイリー 2026"
  },
  {
   "name": "小林美駒",
   "k": "札幌",
   "text": "2026年の札幌で15勝、リーディング2位",
   "src": "デイリー 2026"
  },
  {
   "name": "池添謙一",
   "k": "函館|芝1200",
   "text": "北海道の芝短距離の重賞に強い。人気薄でも買い、と言われる",
   "src": "SPREAD"
  },
  {
   "name": "戸崎圭太",
   "k": "中山|ダ1200",
   "text": "勝率・複勝率がトップ級。ただし人気になるので回収率は高くない",
   "src": "SPAIA"
  },
  {
   "name": "横山典弘",
   "k": "中山|ダ1200",
   "text": "よく来るうえに回収率も悪くない",
   "src": "SPAIA"
  },
  {
   "name": "丸山元気",
   "k": "中山|ダ1200",
   "text": "勝率は高くないが、人気薄で勝つので単勝回収率が目立つ",
   "src": "SPAIA"
  },
  {
   "name": "田辺裕信",
   "k": "中山|ダ1800",
   "text": "勝率と回収率のバランスがいい",
   "src": "SPAIA"
  },
  {
   "name": "石川裕紀人",
   "k": "中山|ダ1800",
   "text": "人気薄での一発がある",
   "src": "SPAIA"
  },
  {
   "name": "横山和生",
   "k": "中山",
   "text": "中山巧者。単勝回収率が100%を超えていた（2021〜23年）。ダートで逃げると人気を裏切りやすい",
   "src": "SPREAD"
  },
  {
   "name": "鮫島克駿",
   "k": "小倉",
   "text": "2024年の冬の小倉でリーディング",
   "src": "デイリー 2024"
  },
  {
   "name": "浜中俊",
   "k": "小倉|芝2000",
   "text": "小倉記念で人気薄でも一発がある",
   "src": "SPREAD"
  },
  {
   "name": "坂井瑠星",
   "k": "全体",
   "text": "逃げて勝つのが上手い。2023年は逃げての勝利が全騎手でいちばん多かった",
   "src": "SPAIA 2023"
  },
  {
   "name": "松山弘平",
   "k": "全体",
   "text": "逃げる回数が多い騎手。2023年の逃げ勝利は2位",
   "src": "SPAIA 2023・JRA-VAN 2019"
  },
  {
   "name": "横山武史",
   "k": "全体",
   "text": "逃げも上手い。2023年の逃げ勝利は3位",
   "src": "SPAIA 2023"
  }
 ],
